const item = $input.first();
if (!item?.json) {
  return [{json: {route: "INVALID", stage: "VALIDATE", error: "No input"}}];
}

// Normalize: webhook v2 wraps payload under json.body
const envelope = item.json;
const hasObjBody = envelope && typeof envelope === "object" && envelope.body && typeof envelope.body === "object" && !Array.isArray(envelope.body);
const data = hasObjBody ? envelope.body : envelope;

if (data.dry_run === true || data.dry_run === "true") {
  return [{json: {route: "VALID_REQUEST", dry_run: true, ...data}}];
}
if (!data.project_id) {
  return [{json: {route: "INVALID_REQUEST", errors: ["Missing project_id"], correlation_id: data.correlation_id || "UNKNOWN"}}];
}
return [{json: {route: "VALID_REQUEST", dry_run: false, ...data}}];
